    static void EnsureInitialized()
    {
        if (_initialized) return;
        _initialized = true;
    }
    static void InitRelicChecks()
    {
        for(int i = 0; i < RELIC_MAX; i++)
        {
            RelicChecks[i].LocId = 0xFF;    // LocId == 0xFF means not in use.
        }
        for(int i = 0; i < 105; i++)
        {
            WhatIsAtLoc[i] = 0xFF;
        }
    }
    static void AddRelicCheck(byte LocId, byte StageId, UInt32 EntityListX, UInt32 EntityListY, byte EquipmentIndex, bool IsItem)
    {
        int RC_Index = 0;
        while (RelicChecks[RC_Index].LocId != 0xFF)
        {
            RC_Index++;
            if (RC_Index >= RELIC_MAX)
            {
                Console.WriteLine("Exceeded maximum number of relic checks.");
                return;
            }
        }

        RelicChecks[RC_Index].LocId = LocId;
        RelicChecks[RC_Index].StageId = StageId;
        RelicChecks[RC_Index].EntityListX = EntityListX;
        RelicChecks[RC_Index].EntityListY = EntityListY;
        RelicChecks[RC_Index].EquipmentIndex = EquipmentIndex;
        RelicChecks[RC_Index].IsItem = IsItem;
    }
