    // This could later be modified to have an item pool rather than completely random items.
    static UInt16 GetRandomItem()
    {
        UInt16 ItemReturn = 0;

        ItemReturn = (UInt16)SeedRNG.Next(1, 259);
        // Filter out certain items.
        while (ItemReturn == ITEM_NOARMOR || ItemReturn == ITEM_SPIKEBREAKER || ItemReturn == ITEM_NOHEAD || ItemReturn == ITEM_HOLYGLASSES || ItemReturn == ITEM_NOCAPE || ItemReturn == ITEM_NOACCESSORY || ItemReturn == ITEM_GOLDRING || ItemReturn == ITEM_SILVERRING)
        {
            ItemReturn = (UInt16)SeedRNG.Next(1, 259);
        }

        ItemReturn += 0x80; // If we want to include Life Max and Heart Max we'll need to give them a spot and return the correct number. Currently this is just equippable items.

        return ItemReturn;
    }

    static UInt16 GetRandomConsumable()
    {
        UInt16 ItemIndex = (UInt16)SeedRNG.Next(0, ConsumableList.Length);
        UInt16 ItemReturn;

        ItemReturn = ConsumableList[ItemIndex];

        return ItemReturn;
    }

    static UInt16 GetRandomWeapon()
    {
        UInt16 ItemIndex = (UInt16)SeedRNG.Next(0, OneHandedWeapons.Length);
        UInt16 ItemReturn;

        ItemReturn = OneHandedWeapons[ItemIndex];

        return ItemReturn;
    }
    static UInt16 GetRandomShield()
    {
        UInt16 ItemReturn = (UInt16)SeedRNG.Next(0, 13);

        if (ItemReturn == 12)
        {
            ItemReturn = 167;   // Alucart Shield
        }
        else
        {
            ItemReturn += 5;    // Adjust Index to line up with the Shields
        }

        return ItemReturn;
    }

    static UInt16 GetRandomHelm()
    {
        UInt16 ItemReturn = (UInt16)SeedRNG.Next(196, 217);

        while(ItemReturn == 203)    // Can't start with Holy Glasses so re-roll
        {
            ItemReturn = (UInt16)SeedRNG.Next(196, 217);
        }

        return ItemReturn;
    }

    static UInt16 GetRandomArmor()
    {
        UInt16 ItemReturn = (UInt16)SeedRNG.Next(170, 195);

        while(ItemReturn == 183)   // Can't start with Spikebreaker so re-roll
        {
            ItemReturn = (UInt16)SeedRNG.Next(170, 195);
        }

        return ItemReturn;
    }

    static UInt16 GetRandomCape()
    {
        UInt16 ItemReturn = (UInt16)SeedRNG.Next(218, 226);

        return ItemReturn;
    }

    static UInt16 GetRandomAccessory()
    {
        UInt16 ItemReturn = (UInt16)SeedRNG.Next(227, 258);

        while(ItemReturn == 241 || ItemReturn == 242)   // Can't start with Gold or Silver Rings
        {
            ItemReturn = (UInt16)SeedRNG.Next(227, 258);
        }

        return ItemReturn;
    }

    static void SetStartingRightHand(UInt16 ItemId, CpuContext c, IMemory m)
    {
        UInt16 InventoryOffset;

        StartingWeapon = ItemId;
        InventoryOffset = (UInt16)(0x798A + ItemId);
        m.WriteU16(0x801001A8, ItemId); // Init
        m.WriteU16(0x800FF800, ItemId); // Check
        m.WriteU16(0x800FF83C, InventoryOffset); // Check Inv
        m.WriteU16(0x800FF850, InventoryOffset); // Check Inv
    }

    static void SetStartingLeftHand(UInt16 ItemId, CpuContext c, IMemory m)
    {
        UInt16 InventoryOffset;

        StartingShield = ItemId;
        InventoryOffset = (UInt16)(0x798A + ItemId);
        m.WriteU16(0x801001B4, ItemId); // Init
        m.WriteU16(0x800FF860, ItemId); // Check
        m.WriteU16(0x800FF89C, InventoryOffset); // Check Inv
        m.WriteU16(0x800FF8B0, InventoryOffset); // Check Inv
    }

    static void SetStartingHelm(UInt16 ItemId, CpuContext c, IMemory m)
    {
        UInt16 InventoryOffset;

        StartingHelm = ItemId;
        InventoryOffset = (UInt16)(0x798A + ItemId);
        ItemId -= 169;
        m.WriteU16(0x801001C0, ItemId); // Init
        m.WriteU16(0x800FF8C0, ItemId); // Check
        m.WriteU16(0x800FF8D8, InventoryOffset); // Check Inv
        m.WriteU16(0x800FF8EC, InventoryOffset); // Check Inv
    }

