    public static void DoRandomizeStartingGear(CpuContext c, IMemory m)
    {
        bool DEBUG_OUT = true;

        SetStartingRightHand( GetRandomWeapon(), c, m );
        SetStartingLeftHand( GetRandomShield(), c, m );
        SetStartingHelm(  GetRandomHelm(), c, m );
        SetStartingArmor( GetRandomArmor(), c, m );
        SetStartingCape( GetRandomCape(), c, m );
        SetStartingAccessory( GetRandomAccessory(), c, m );

        if(DEBUG_OUT)
        {
            Console.WriteLine("Starting Weapon: 0x" + StartingWeapon.ToString("X2"));
            Console.WriteLine("Starting Shield: 0x" + StartingShield.ToString("X2"));
            Console.WriteLine("Starting Helm: 0x" + StartingHelm.ToString("X2"));
            Console.WriteLine("Starting Body: 0x" + StartingArmor.ToString("X2"));
            Console.WriteLine("Starting Cape: 0x" + StartingCape.ToString("X2"));
            Console.WriteLine("Starting Accessory: 0x" + StartingAccessory.ToString("X2"));
        }

        // Take Away
        m.WriteU16(0x800FF800, StartingWeapon);
        m.WriteU16(0x800FF860, StartingShield);
        m.WriteU16(0x800FF8C0, (UInt16)(StartingHelm - 169));
        m.WriteU16(0x800FF8FC, (UInt16)(StartingArmor - 169));
        m.WriteU16(0x800FF938, (UInt16)(StartingCape - 169));
        m.WriteU16(0x800FF97C, (UInt16)(StartingAccessory - 169));

        // Todo: Update values for looking in Inventory count to find starting gear.

        // Start With
        m.WriteU16(0x801001A8, StartingWeapon);
        m.WriteU16(0x801001B4, StartingShield);
        m.WriteU16(0x801001C0, (UInt16)(StartingHelm - 169));
        m.WriteU16(0x801001CC, (UInt16)(StartingArmor - 169));
        m.WriteU16(0x801001D8, (UInt16)(StartingCape - 169));
        m.WriteU16(0x801001E4, (UInt16)(StartingAccessory - 169));
    }

    public static void UpdateDeathStealIcons(CpuContext c, IMemory m)
    {
        // Icon Update
        m.WriteU16(0x80181AD4, (UInt16)StartingWeapon);
        m.WriteU16(0x80181AD6, (UInt16)StartingShield);
        m.WriteU16(0x80181AD8, (UInt16)StartingHelm);
        m.WriteU16(0x80181ADA, (UInt16)StartingArmor);
        m.WriteU16(0x80181ADC, (UInt16)StartingCape);
        m.WriteU16(0x80181ADE, (UInt16)StartingAccessory);
    }

    static void ResetItemPickPool()
    {
        for (int i = 0; i < 260; i++) { ItemPickedOnce[i] = 0; }   // Reset Pool
    }

    static void RemoveGemsFromPickPool()
    {
        for (int i = 232; i < 239; i++) { ItemPickedOnce[i] = 1; }   // Set already Picked.
    }

    static void DoRandomizePrologueRewards()
    {
        UInt16 ItemPick;

        ResetItemPickPool();
        for (int i = 0; i < 3; i++)
        {
            do
            {
                ItemPick = GetRandomConsumable();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            PrologueRewardItems[i] = ItemPick;
        }
    }

    static void DoRandomizeShop()
    {
        UInt16 ItemPick;

        ResetItemPickPool();
        for (int i = 0; i < 18; i++)
        {
            do
            {   ItemPick = GetRandomConsumable();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
        }

        ResetItemPickPool();
        for (int i = 18; i < 25; i++)
        {
            do
            {
                ItemPick = GetRandomWeapon();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
        }

        ResetItemPickPool();
        for (int i = 25; i < 27; i++)
        {
            do
            {
                ItemPick = GetRandomShield();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
        }

        ResetItemPickPool();
        for (int i = 27; i < 31; i++)
        {
            do
            {
                ItemPick = GetRandomHelm();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
            ShopItems[i] -= 169;
        }

        ResetItemPickPool();
        for (int i = 31; i < 34; i++)
        {
            do
            {
                ItemPick = GetRandomArmor();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
            ShopItems[i] -= 169;
        }

        ResetItemPickPool();
        for (int i = 34; i < 37; i++)
        {
            do
            {
                ItemPick = GetRandomCape();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
            ShopItems[i] -= 169;
        }

        ResetItemPickPool();
        RemoveGemsFromPickPool();
        for (int i = 37; i < 41; i++)
        {
            do
            {
                ItemPick = GetRandomAccessory();
            } while (ItemPickedOnce[ItemPick] == 1);

            ItemPickedOnce[ItemPick] = 1;
            ShopItems[i] = ItemPick;
            ShopItems[i] -= 169;
        }
    }

    static void ApplyRandomizedShop(CpuContext c, IMemory m)
    {
        UInt32 ShopPointer = 0x80181356;
        for (int i = 0; i < 41; i++)
        {
            m.WriteU16(ShopPointer, ShopItems[i]);
            ShopPointer += 8;
        }
    }

   static void ApplyPrologueRewards(CpuContext c, IMemory m)
    {
        m.WriteU16(0x800FFDC0, PrologueRewardItems[0]);
        m.WriteU16(0x800FFEAC, PrologueRewardItems[1]);
        m.WriteU16(0x800FFF08, PrologueRewardItems[2]);
    }

    public static void RandomizeSeedNumber()
    {
        SeedNumber = Random.Shared.Next(0, 0x7FFFFFFF);
        SaveSeed();
    }

    static bool _seedLoaded;

    public static void EnsureSeedLoaded()
    {
        if (_seedLoaded)
            return;
        _seedLoaded = true;
        SeedNumber = RecompOne.Runtime.Runtime.View.GetInt("Rando.SeedNumber", SeedNumber);
        RandomizeItems = RecompOne.Runtime.Runtime.View.GetBool("Rando.RandomizeItems", RandomizeItems);
        RandomizeDrops = RecompOne.Runtime.Runtime.View.GetBool("Rando.RandomizeDrops", RandomizeDrops);
        RandomizeRelics = RecompOne.Runtime.Runtime.View.GetBool("Rando.RandomizeRelics", RandomizeRelics);
        RandomizeStartingGear = RecompOne.Runtime.Runtime.View.GetBool("Rando.RandomizeStartingGear", RandomizeStartingGear);
        RemoveDeathFromEntrance = RecompOne.Runtime.Runtime.View.GetBool("Rando.RemoveDeathFromEntrance", RemoveDeathFromEntrance);
    }

    static void SaveSeed()
    {
        RecompOne.Runtime.Runtime.View.SetInt("Rando.SeedNumber", SeedNumber);
        RecompOne.Runtime.Runtime.View.SetBool("Rando.RandomizeItems", RandomizeItems);
        RecompOne.Runtime.Runtime.View.SetBool("Rando.RandomizeDrops", RandomizeDrops);
        RecompOne.Runtime.Runtime.View.SetBool("Rando.RandomizeRelics", RandomizeRelics);
        RecompOne.Runtime.Runtime.View.SetBool("Rando.RandomizeStartingGear", RandomizeStartingGear);
        RecompOne.Runtime.Runtime.View.SetBool("Rando.RemoveDeathFromEntrance", RemoveDeathFromEntrance);
        RecompOne.Runtime.Runtime.SaveView();
    }

    public static void RandomizeSeed()
    {
        var m = RecompOne.Runtime.Runtime.Mem;
        var c = RecompOne.Runtime.Runtime.Cpu;

        if (m == null || c == null)
            return;

        // If Preset is not None aka Vanilla game don't do anything.
        if (m.ReadU8(0x8000C000) != (byte)PresetId.None)
            return;

        // If no options selected, don't do anything.
        if (RandomizeItems == false && RandomizeDrops == false && RandomizeRelics == false)
            return;

        // Update Preset to Integrated
        m.WriteU8(0x8000C000, (byte)PresetId.Integrated);

        SaveSeed();

        // Seed the RNG with our starting seed number. In theory this creates a recreateable seed?
        SeedRNG = new Random(SeedNumber);

        if (RandomizeDrops == true)
            DoRandomizeDrops();

        if (RandomizeItems == true)
        {
            DoRandomizeItems();
            DoRandomizeShop();
            DoRandomizePrologueRewards();
        }
            

        if (RandomizeRelics == true)
            DoRandomizeRelics();

        if (RandomizeStartingGear == true)
            DoRandomizeStartingGear(c, m);

        // Turn on Bug Fixes when playing randomizer. No real reason not to have them on.
        QualityOfLife.BugFixes = true;
    }

    public static void DoRandomizeDrops()
    {
        UInt16 RandomItemId;

        for (int i = 0; i < 800; i++)
        {
            /*
            RandomItemId = 169;
            while(RandomItemId == 169 || RandomItemId == 183 || RandomItemId == 195 || RandomItemId == 203 || RandomItemId == 217 || RandomItemId == 226 || RandomItemId == 241 || RandomItemId == 242)
            {
                RandomItemId = (UInt16)SeedRNG.Next(1, 259);
            }
            */
            RandomItemId = GetRandomItem();

            //RandomItemId += 0x80;
            EnemyDrops[i] = RandomItemId;  // Item base starts at 0x80.
        }
    }

    public static void DoRandomizeItems()
    {
        int ItemIndex = 0;

        for(int StageId = 0; StageId < 0x2E; StageId++)
        {
            if (StageId == 0x1B)    // Skip Scylla
                StageId++;
            ItemIndex = 0;
            while (ItemIndex < (byte)StageItemListLength[StageId])
            {
                //Console.WriteLine("Item Index is:" + ItemIndex + " StageId:" + StageId);
                StageItems[StageId,ItemIndex] = GetRandomItem();
                ItemIndex++;
            }
        }

        // Copy 0x07 to 0x41 for Entrance
        for (int i = 0; i < (byte)StageItemListLength[0x07]; i++)
        {
            StageItems[0x41, i] = StageItems[0x07, i];
        }

        // Copy 0x09 to 0x1B for Scylla
        for (int i = 0; i < (byte)StageItemListLength[0x09]; i++)
        {
            StageItems[0x1B, i] = StageItems[0x09, i];
        }

        // Silver Ring is at 0x06,2
        StageItems[0x06, 2] = ITEM_SILVERRING + 0x80;
        // Gold Ring is at 0x09,0xA
        StageItems[0x09, 0xA] = ITEM_GOLDRING + 0x80;
        // Spikebreaker is at 0x03,0x10
        StageItems[0x03, 0x10] = ITEM_SPIKEBREAKER + 0x80;
    }

    public static void DoRandomizeRelics()
    {
        bool RELIC_DEBUG = false;
        UInt16 RelicConfigIndex = (UInt16)SeedRNG.Next(0, 1024);
        SetupRelicChecks();

        // Copy Relic Data from Database
        for (int i=0; i < 34; i++)
        {
            WhereIsRelic[i] = RelicConfigs[(RelicConfigIndex) * 34 + i];    // This tells us where each of the 34 Relics are.
        }

        // Use the location for each relic to set those relics in place.
        for(int i=0;i < 34; i++)
        {
            WhatIsAtLoc[WhereIsRelic[i]] = (byte)i;
        }

        // DEBUG USE
        if(RELIC_DEBUG)
        {
            for (int i = 0; i < 105; i++)
            {
                // Item Testing, Force Item Everywhere
                //WhatIsAtLoc[i] = (byte)RelicIdNumber.SPIKEBREAKER;
                // Relic Testing, Force Relic Everywhere
                //WhatIsAtLoc[i] = (byte)RelicIdNumber.FIREOFBAT;
            }

            for (int i = 0; i < 37; i++)    // Show Placements
            {
                if (WhatIsAtLoc[i] != 0xFF)
                    Console.WriteLine("Location: " + LocationNames[i] + "has " + RelicNames[WhatIsAtLoc[i]]);
                else
                    Console.WriteLine("Location: " + LocationNames[i] + "has nothing.");
            }
        }

    }

    // Hooked to Stage Overlay Load. Applies writes to DRA and Stage Overlays for Randomization.
    public static void ApplyInternalRandomizer(CpuContext c, IMemory m)
    {
        UInt32 EnemyDefPtr = 0x800A8900;
        UInt16 UncommonItem;
        UInt16 RareItem;
        byte StageId = m.ReadU8(0x800974a0);

        if (m.ReadU8(0x8000C000) != (byte)PresetId.Integrated)
            return;

        // Debug!
        //m.WriteU8(0x80098850, 1);

        if (RandomizeDrops == true)
        {
            for(int i = 0; i < 400; i++)
            {
                UncommonItem = EnemyDrops[(i * 2)];
                RareItem = EnemyDrops[(i * 2)+1];
                m.WriteU16(EnemyDefPtr + 0x1A, UncommonItem);
                m.WriteU16(EnemyDefPtr + 0x1C, RareItem);
                EnemyDefPtr = EnemyDefPtr + 0x28;
            }
        }

        if(RandomizeItems == true)
        {

            int ItemIndex = 0;
            UInt32 StageListAddress = StageItemListOffset[StageId];

            if (StageItemListOffset[StageId] > 0)
            {
                while (ItemIndex < StageItemListLength[StageId])
                {
                    m.WriteU16(StageListAddress, StageItems[StageId, ItemIndex]);
                    StageListAddress += 2;
                    ItemIndex++;
                }
            }

            if (StageId == 0x02)
                ApplyRandomizedShop(c, m);

            ApplyPrologueRewards(c, m);
        }

        if(RandomizeRelics == true)
        {
            ApplyRelicWrites(c, m);
        }

        if(StageId == 0x41)
        {
            if (RemoveDeathFromEntrance == true)
            {
                m.WriteU8(0x8003BE21, 1);
            }
            if(RandomizeStartingGear == true)
            {
                UpdateDeathStealIcons(c, m);
            }
        }

    }

    public static void ApplyRelicWrites(CpuContext c, IMemory m)
    {
        byte StageId = m.ReadU8(0x800974a0);
        UInt16 RelicId;
        UInt16 EntityType;

        // For all generic checks
        for (int RI = 0; RI < RELIC_MAX; RI++)
        {
            if (RelicChecks[RI].LocId == 0xFF)
                break;

            EntityType = 0xB;
            RelicId = WhatIsAtLoc[RelicChecks[RI].LocId];
            if(RelicId > (UInt16)RelicIdNumber.EYEOFVLAD)
            {
                EntityType = 0xA;
                
                if (RelicId == (UInt16)RelicIdNumber.GOLDRING)
                    RelicId = ITEM_GOLDRING;
                if (RelicId == (UInt16)RelicIdNumber.SILVERRING)
                    RelicId = ITEM_SILVERRING;
                if (RelicId == (UInt16)RelicIdNumber.HOLYGLASSES)
                    RelicId = ITEM_HOLYGLASSES;
                if (RelicId == (UInt16)RelicIdNumber.SPIKEBREAKER)
                    RelicId = ITEM_SPIKEBREAKER;

                if (RelicId == 0xFF)
                    RelicId = 0;
                RelicId |= 0x8000;
            }

            if (StageId == RelicChecks[RI].StageId)
            {
                m.WriteU16(RelicChecks[RI].EntityListX + 4, EntityType);
                m.WriteU16(RelicChecks[RI].EntityListX + 8, RelicId);
                if(RelicChecks[RI].EntityListY > 0)
                {
                    m.WriteU16(RelicChecks[RI].EntityListY + 4, EntityType);
                    m.WriteU16(RelicChecks[RI].EntityListY + 8, RelicId);
                }
            }
        }

        // Do Special Checks
        if (StageId == 0x0C)
            UpdateAlchemyGlassOrbs(c, m);

        if (StageId == 0x08)
            UpdateHolyGlasses(c, m);

        if (StageId == 0x09)
            UpdateGoldRing(c, m);

        if (StageId == 0x02)
            UpdateJewelOfOpen(c, m);

        UpdateReverseCastleBossRelics(c, m);
    }

    public static byte RelicIdToItemNumber(byte RelicId)
    {
        if (RelicId == (byte)RelicIdNumber.GOLDRING)
            return ITEM_GOLDRING;
        if (RelicId == (byte)RelicIdNumber.SILVERRING)
            return ITEM_SILVERRING;
        if (RelicId == (byte)RelicIdNumber.HOLYGLASSES)
            return ITEM_HOLYGLASSES;
        if (RelicId == (byte)RelicIdNumber.SPIKEBREAKER)
            return ITEM_SPIKEBREAKER;
        return 0;
    }

    public static void UpdateAlchemyGlassOrbs(CpuContext c, IMemory m)
    {
        UInt16 RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_SKILLOFWOLF];
        
        // If has Item or Nothing
        if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
        {
            if(RelicId == 0xFF)
            {
                m.WriteU8(0x80183058, 3);
                m.WriteU8(0x8018305C, 0);
            }
            else
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x80183058, 0xA);
                m.WriteU16(0x8018305C, RelicId);
            }
        }
        else
        {
            m.WriteU16(0x80180FA2, RelicId);
        }

        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_BATCARD];

        // If has Item or Nothing
        if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
        {
            if (RelicId == 0xFF)
            {
                m.WriteU8(0x80182A90, 3);
                m.WriteU8(0x80182A94, 0);
            }
            else
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x80182A90, 0xA);
                m.WriteU16(0x80182A94, RelicId);
            }
        }
        else
        {
            m.WriteU16(0x80180FA0, RelicId);
        }
    }

    public static void UpdateHolyGlasses(CpuContext c, IMemory m)
    {
        byte RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_HOLYGLASSES];
        UInt32 HGOFFSET;

        // If has Item or Nothing
        if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
        {
            if (RelicId == 0xFF)
            {
                m.WriteU8(0x8018FEA0, 0);
            }
            else
            {
                RelicId = RelicIdToItemNumber(RelicId);
                m.WriteU8(0x8018FEA0, RelicId);
            }
        }
        else
        {
            // Is Relic
            m.WriteU8(0x8018FEA0, 0);   // Remove Item.
            HGOFFSET = 0x80181328;
            for(int i = 0;i < 2; i++)
            {
                m.WriteU16(HGOFFSET + 0, 0x180);
                m.WriteU16(HGOFFSET + 2, 0x22E);
                m.WriteU16(HGOFFSET + 4, 0x00B);
                m.WriteU16(HGOFFSET + 6, 0x010);
                m.WriteU16(HGOFFSET + 8, RelicId);
                HGOFFSET = 0x801813BE;
            }
        }
    }

    public static void UpdateGoldRing(CpuContext c, IMemory m)
    {
        UInt16 RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_GOLDRING];

        // If has Item or Nothing
        if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
        {
            if (RelicId == 0xFF)
            {
                m.WriteU16(0x8018193C, 0);
            }
            else
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId += 0x80;
                m.WriteU16(0x8018193C, RelicId);
            }
        }
        else
        {
            // Is Relic
            m.WriteU32(0x801CC590, 0x08077AED); // Make it a Relic by using the rando patch detection word.
            m.WriteU16(0x80184278, RelicId);    // Update Relic Number
        }
    }

    public static void UpdateJewelOfOpen(CpuContext c, IMemory m)
    {
        byte RelicStringByte;
        byte RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_JEWELOFOPEN];
        UInt16 RelicMemAddress = 0x7964;

        // If has Item or Nothing
        if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
        {
            if (RelicId == 0xFF)
            {
                m.WriteU16(0x8018134C, 0);
                m.WriteU16(0x8018134E, 0);
            }
            else
            {
                RelicId = RelicIdToItemNumber(RelicId);
                RelicId = RelicId -= 169;
                m.WriteU16(0x8018134C, 0xFF01);
                m.WriteU16(0x8018134E, RelicId);

                // This address will be checked to see if Item is old of stock.
                if (WhatIsAtLoc[(byte)RelicLocationId.LOC_JEWELOFOPEN] == (byte)RelicIdNumber.GOLDRING)
                    m.WriteU16(0x801B2B08, 0x7A7B);
                if (WhatIsAtLoc[(byte)RelicLocationId.LOC_JEWELOFOPEN] == (byte)RelicIdNumber.SILVERRING)
                    m.WriteU16(0x801B2B08, 0x7A7C);
                if (WhatIsAtLoc[(byte)RelicLocationId.LOC_JEWELOFOPEN] == (byte)RelicIdNumber.HOLYGLASSES)
                    m.WriteU16(0x801B2B08, 0x7A55);
                if (WhatIsAtLoc[(byte)RelicLocationId.LOC_JEWELOFOPEN] == (byte)RelicIdNumber.SPIKEBREAKER)
                    m.WriteU16(0x801B2B08, 0x7A41);
            }
        }
        else
        {
            // Is Relic
            m.WriteU8(0x801814D4, RelicId);    // Update Relic Number
            RelicMemAddress += RelicId;
            m.WriteU16(0x801B2B08, RelicMemAddress);

            // Update Relic Name
            for(UInt32 i = 0; i < RelicNames[RelicId].Length; i++)
            {
                RelicStringByte = (byte)RelicNames[RelicId][(int)i];
                RelicStringByte -= 0x20;
                m.WriteU8(0x801AD088 + i, RelicStringByte);
            }
            m.WriteU8(0x801AD088 + (UInt32)RelicNames[RelicId].Length, 0xFF);
            m.WriteU8(0x801AD088 + (UInt32)RelicNames[RelicId].Length + 1, 0x00);

        }
    }

    public static void UpdateReverseCastleBossRelics(CpuContext c, IMemory m)
    {
        byte StageId = m.ReadU8(0x800974a0);
        UInt16 RelicId;

        // Trio in 3E
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_TRIO];
        if (StageId == 0x3E)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                if (RelicId != 0xFF)
                {
                    RelicId = RelicIdToItemNumber((byte)RelicId);
                    RelicId += 0x80;
                    m.WriteU16(0x8018198C, RelicId);    // Default Reward index is 2, so update index 0 with new item number
                }
            }
            else
            {
                //m.WriteU16(0x801A6148, 0x0148);
                //m.WriteU16(0x8018198C, RelicId);
                m.WriteU16(0x8019465C, 0x11);   // Change Reward Index to 0x11
                m.WriteU16(0x801819AA, RelicId);// Update Reward in Slot 0x11
            }
        }

        // Trio in 2A
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_TRIO];
        if (StageId == 0x2A)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                if (RelicId != 0xFF)
                {
                    RelicId = RelicIdToItemNumber((byte)RelicId);
                    RelicId |= 0x8000;
                    m.WriteU16(0x801823B0 + 0, 0x0100);
                    m.WriteU16(0x801823B0 + 2, 0x00A8);
                    m.WriteU16(0x801823B0 + 4, 0x000A);
                    m.WriteU16(0x801823B0 + 6, 0x0010);
                    m.WriteU16(0x801823B0 + 8, RelicId);
                }
            }
            else
            {
                m.WriteU16(0x801823B0 + 0, 0x0100);
                m.WriteU16(0x801823B0 + 2, 0x00A8);
                m.WriteU16(0x801823B0 + 4, 0x000B);
                m.WriteU16(0x801823B0 + 6, 0x0010);
                m.WriteU16(0x801823B0 + 8, RelicId);
            }
        }

        // Heart of Vlad in 3B (rbo3)
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_HEARTOFVLAD];
        if (StageId == 0x3B)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId += 0x80;
                m.WriteU16(0x801812A8, RelicId);    // Set Reward Index 0 to Item ID
                m.WriteU16(0x80192CBC, 0x0000);     // Change Function to Use Reward 0
            }
            else
            {
                m.WriteU16(0x801812CA, RelicId);
            }
        }

        // Heart of Vlad in 26
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_HEARTOFVLAD];
        if (StageId == 0x26)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x80181DC4+8, RelicId);
                m.WriteU16(0x80181DC4+4, 0x0A); // change to item
            }
            else
            {
                m.WriteU16(0x80181DC4+8, RelicId);
            }
        }

        // todo, tooth, rib, ring, eye
        // Tooth of Vlad in 3A (rbo4)
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_TOOTHOFVLAD];
        if (StageId == 0x3A)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId += 0x80;
                m.WriteU16(0x801813B4, RelicId);    // Set Reward Table Index 0 to Item ID
                m.WriteU16(0x80198970, 0x0000);     // Change Function to Use Reward 0
            }
            else
            {
                m.WriteU16(0x801813D8, RelicId);    // Update Reward Relic ID
            }
        }

        // Tooth of Vlad in 21
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_TOOTHOFVLAD];
        if (StageId == 0x21)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x80182332 + 8, RelicId);    // Change Entity Init
                m.WriteU16(0x80182332 + 4, 0x0A);       // Change Entity Type
            }
            else
            {
                m.WriteU16(0x80182332 + 8, RelicId);
            }
        }

        // Rib of Vlad in 37 (rbo7)
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_RIBOFVLAD];
        if (StageId == 0x37)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId += 0x80;
                m.WriteU16(0x80181300, RelicId);    // Set Reward Table Index 0 to Item ID
                m.WriteU16(0x8019400C, 0x0000);     // Change Function to Use Reward 0
            }
            else
            {
                m.WriteU16(0x80181326, RelicId);    // Update Reward Relic ID
            }
        }

        // Rib of Vlad in 24
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_RIBOFVLAD];
        if (StageId == 0x24)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x801829D4 + 8, RelicId);    // Change Entity Init
                m.WriteU16(0x801829D4 + 4, 0x0A);       // Change Entity Type
                m.WriteU16(0x801831B8 + 8, RelicId);    // repeat for Y-list
                m.WriteU16(0x801831B8 + 4, 0x0A); 
            }
            else
            {
                m.WriteU16(0x801829D4 + 8, RelicId);    // Change Entity Init
                m.WriteU16(0x801831B8 + 8, RelicId);    // repeat for Y-list
            }
        }

        // Ring of Vlad in 0x2D
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_RINGOFVLAD];
        if (StageId == 0x2D)
        {
            // For Item
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;

                m.WriteU16(0x801AC84C, 0x26EC);     // Change Function Pointer lower 16-bits for Item Entity 0xA for Already Dead state.
                m.WriteU16(0x801AC85C, RelicId);    // Created Item 0xA Init Value

                RelicId += 0x80;
                m.WriteU16(0x801ACB0C, 0x0000);     // Changes Reward Index for Spawn
                m.WriteU16(0x80182570, RelicId);    // Update Reward Table at Index 0
            }
            else
            {
                // For Relic
            }
            {
                m.WriteU16(0x801AC85C, RelicId);    // Update Dead Relic ID
                m.WriteU16(0x80182598, RelicId);    // Update Swirl Relic ID
            }
        }

        // Eye of Vlad in 0x3C (rbo2)
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_EYEOFVLAD];
        if (StageId == 0x3C)
        {
            // For Item
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId += 0x80;
                m.WriteU16(0x80181788, RelicId);    // Set Reward Table Index 0 to Item ID
                m.WriteU16(0x8019F728, 0x0000);     // Change Function to Use Reward 0
            }
            else   // For Relic
            {
                m.WriteU16(0x801817B2, RelicId);    // Update Reward Relic ID
            }
        }

        // Eye of Vlad in 0x25
        RelicId = WhatIsAtLoc[(byte)RelicLocationId.LOC_EYEOFVLAD];
        if (StageId == 0x25)
        {
            if (RelicId > (byte)RelicIdNumber.EYEOFVLAD)
            {
                RelicId = RelicIdToItemNumber((byte)RelicId);
                RelicId |= 0x8000;
                m.WriteU16(0x801818F2 + 8, RelicId);// Update Relic Id
                m.WriteU16(0x801818F2 + 4, 0x0A);   // Change Entity Type
                m.WriteU16(0x801818F2 + 2, 0x78);   // Update Y-Pos so Item can Spawn
            }
            else
            {
                m.WriteU16(0x801818F2 + 8, RelicId);
            }
        }

    }
}
